        return { ok: false };
    }
    var sel = selectResolvableThreadsFor(provider, prNumber, headSha, logins, cfg);
    if (sel.gate !== 'approve') {
        console.log('  ⏭️  resolveSuggestionThreads on PR #' + prNumber +
