test('gh-1352 BLOCKING replay: two deferrals in one tick BOTH land in the final ledger marker (memoized provider)', function () {
    var comments = [
        { user: { login: 'ai-teammate' }, body: '<!-- dmtools:review-verdict ' + JSON.stringify({
